def foes():
    mobs=[]; bosses=[]
    for f,(family,body,skill,loss,reach) in enumerate(families):
        area=f//3
        for v,(tag,trait,_) in enumerate(variants):
            t=v//2+1; i=f*10+v; key=f'M{i+1:03}'
            mobs.append(dict(id=key,name=family+' · '+tag,area=area,t=t,hp=3+2*(t-1),defense=7+t,dmg=2+(t-1)//2,reach=int(reach),body=body,seed=v+f*13,ability=skill,trait=trait,loss=loss))
    for a,names in enumerate(bossnames):
        for v,entry in enumerate(names):
            name,omen=entry.split(':');t=v//2+1;s=signals[a];i=a*10+v
            bosses.append(dict(id=f'B{i+1:03}',name=name,area=a,t=t,hp=5+2*t+max(0,t-2),defense=7+t,dmg=3+(t-1)//2+int(t>=4),reach=v%2+int(v==8),body=forms[a][v],seed=i+393,decree=edicts[a][v],ability=phases[(v+2*a)%10],omen=omen.capitalize()+'.',signal=s[0]+': '+s[1]+'.',counter=s[2].capitalize()+' в зоне сигнала: 1 действие без броска.',loss=penalties[(a+v)%10]))
    return mobs,bosses
